import pandas as pd

def user_activities(sessions: pd.DataFrame) -> pd.DataFrame:
    if sessions.empty:
        return pd.DataFrame(columns=['user_id'])
    df = sessions.sort_values(by=['user_id', 'session_type', 'session_start']).copy()
    df['session_start'] = pd.to_datetime(df['session_start'])
    df['session_end'] = pd.to_datetime(df['session_end'])
    df['prev_end'] = df.groupby(['user_id', 'session_type'])['session_end'].shift(1)
    diff = (df['session_start'] - df['prev_end']).dt.total_seconds()
    valid = df[(diff >= 0) & (diff <= 43200)]['user_id'].drop_duplicates().sort_values()
    return pd.DataFrame({'user_id': valid})
